def build_book(root,cfg,dest_dir,open_browser=False):
    src_name,src_path=get_src_dir(root,cfg)
    summary_path=os.path.join(src_path,'SUMMARY.md')
    if not os.path.exists(summary_path):
        error_exit(f"Couldn't open SUMMARY.md in \"{src_path}\" directory","No such file or directory (os error 2)")
    toc_tree,has_numbered=parse_summary(summary_path)
    if toc_tree is None:
        error_exit(f"Couldn't open SUMMARY.md in \"{src_path}\" directory","No such file or directory (os error 2)")
    assign_numbers(toc_tree)
    create_missing=cfg['build'].get('create-missing',True)
    if isinstance(create_missing,str): create_missing=create_missing.lower() in ('true','1','yes')
    ensure_chapter_files(root,src_path,toc_tree,create_missing)
    flat=flatten_chapters(toc_tree)
    sys.stderr.write('2026-09-08 17:49:19 [INFO] (mdbook_driver::mdbook): Book building has started\n')
    sys.stderr.write('2026-09-08 17:49:19 [INFO] (mdbook_driver::mdbook): Running the html backend\n')
    os.makedirs(dest_dir,exist_ok=True)
    theme_dir=os.path.join(root,'theme')
    if not os.path.isdir(theme_dir): theme_dir=None
    copy_static_assets(dest_dir,theme_dir)
    chapter_htmls=[]
    nav_list=[]
