    src_path=os.path.join(dir_path,src_name)
    if args.theme:
        theme_path=os.path.join(dir_path,'theme')
        sys.stdout.write(f'Copying the default theme to {theme_path}\n')
        os.makedirs(theme_path,exist_ok=True)
        default_assets=load_static_assets()
        theme_files=['book.js','css/chrome.css','css/general.css','css/print.css','css/variables.css','favicon.png','favicon.svg','fonts/OPEN-SANS-LICENSE.txt','fonts/SOURCE-CODE-PRO-LICENSE.txt','fonts/fonts.css','fonts/open-sans-v17-all-charsets-300.woff2','fonts/open-sans-v17-all-charsets-300italic.woff2','fonts/open-sans-v17-all-charsets-600.woff2','fonts/open-sans-v17-all-charsets-600italic.woff2','fonts/open-sans-v17-all-charsets-700.woff2','fonts/open-sans-v17-all-charsets-700italic.woff2','fonts/open-sans-v17-all-charsets-800.woff2','fonts/open-sans-v17-all-charsets-800italic.woff2','fonts/open-sans-v17-all-charsets-italic.woff2','fonts/open-sans-v17-all-charsets-regular.woff2','fonts/source-code-pro-v11-all-charsets-500.woff2','highlight.css','highlight.js','index.hbs']
        for rel in theme_files:
            data=default_assets.get(rel)
            if data:
                dest=os.path.join(theme_path,rel)
                os.makedirs(os.path.dirname(dest),exist_ok=True)
                with open(dest,'wb') as out: out.write(data)
    title=args.title; ignore=args.ignore
    if not args.force:
        if ignore is None:
            sys.stdout.write("\nDo you want a .gitignore to be created? (y/n)\n")
            sys.stdout.flush()
            ans=sys.stdin.readline().strip()
            ignore='git' if ans.lower()=='y' else 'none'
        if title is None:
            sys.stdout.write("What title would you like to give the book? \n")
            sys.stdout.flush()
            ti=sys.stdin.readline().strip()
            title=ti if ti!='' else None
    gitignore_path=os.path.join(dir_path,'.gitignore')
    if ignore=='git' and not os.path.exists(gitignore_path):
        with open(gitignore_path,'w',encoding='utf-8') as f: f.write("book\n")
    if os.path.exists(book_toml_path):
        if title is not None:
            with open(book_toml_path,'w',encoding='utf-8') as f:
                f.write('[book]\n'); f.write('authors = []\n'); f.write('language = "en"\n'); f.write('src = "src"\n'); f.write(f'title = "{title}"\n')
            src_name='src'; src_path=os.path.join(dir_path,src_name)
    else:
        with open(book_toml_path,'w',encoding='utf-8') as f:
            f.write('[book]\n'); f.write('authors = []\n'); f.write('language = "en"\n'); f.write('src = "src"\n')
            if title: f.write(f'title = "{title}"\n')
        src_name='src'; src_path=os.path.join(dir_path,src_name)
    os.makedirs(src_path,exist_ok=True)
    summary_path=os.path.join(src_path,'SUMMARY.md')
    if os.path.exists(summary_path):
        toc_tree,_=parse_summary(summary_path)
        if toc_tree: ensure_chapter_files(dir_path,src_path,toc_tree,True)
    else:
