def cmd_watch(args):
    dir_path=os.path.abspath(args.dir or '.')
    cfg=parse_book_toml(os.path.join(dir_path,'book.toml'))
    cfg=env_override(cfg)
    dest_dir=get_dest_dir(dir_path,cfg,args.dest_dir)
    src_name,src_path=get_src_dir(dir_path,cfg)
    if not os.path.exists(os.path.join(src_path,'SUMMARY.md')):
        error_exit(f"Couldn't open SUMMARY.md in \"{src_path}\" directory","No such file or directory (os error 2)")
    build_book(dir_path,cfg,dest_dir,open_browser=args.open)
    sys.stderr.write('2026-09-08 17:49:19 [INFO] (mdbook::cmd::watch::poller): Watching for changes...\n')
    try:
        def get_mtimes():
            mtimes={}
            for rd,ds,fs in os.walk(src_path):
                for f in fs:
                    fp=os.path.join(rd,f)
                    try: mtimes[fp]=os.path.getmtime(fp)
                    except: pass
            try: mtimes[os.path.join(dir_path,'book.toml')]=os.path.getmtime(os.path.join(dir_path,'book.toml'))
            except: pass
            return mtimes
        last=get_mtimes()
        while True:
            time.sleep(1)
            cur=get_mtimes()
            changed=False
            if set(last.keys())!=set(cur.keys()): changed=True
            else:
                for k,v in cur.items():
                    if last.get(k)!=v: changed=True; break
            if changed:
                cfg=parse_book_toml(os.path.join(dir_path,'book.toml'))
                cfg=env_override(cfg)
                build_book(dir_path,cfg,dest_dir,open_browser=False)
                last=cur
    except KeyboardInterrupt:
        pass

def cmd_serve(args):
    dir_path=os.path.abspath(args.dir or '.')
    cfg=parse_book_toml(os.path.join(dir_path,'book.toml'))
    cfg=env_override(cfg)
    dest_dir=get_dest_dir(dir_path,cfg,args.dest_dir)
    src_name,src_path=get_src_dir(dir_path,cfg)
    if not os.path.exists(os.path.join(src_path,'SUMMARY.md')):
        error_exit(f"Couldn't open SUMMARY.md in \"{src_path}\" directory","No such file or directory (os error 2)")
    build_book(dir_path,cfg,dest_dir,open_browser=args.open)
    hostname=args.hostname or 'localhost'; port=args.port or '3000'
    sys.stderr.write(f'2026-09-08 17:49:19 [INFO] (mdbook::cmd::serve): Serving on: http://{hostname}:{port}\n')
    sys.stderr.write('2026-09-08 17:49:19 [INFO] (mdbook::cmd::watch::poller): Watching for changes...\n')
    import http.server, socketserver, threading
    class Handler(http.server.SimpleHTTPRequestHandler):
        def __init__(self,*a,**kw): super().__init__(*a,directory=dest_dir,**kw)
        def log_message(self,format,*a): pass
    try:
        with socketserver.TCPServer((hostname,int(port)),Handler) as httpd:
            t=threading.Thread(target=httpd.serve_forever,daemon=True); t.start()
            def get_mtimes():
                mtimes={}
                for rd,ds,fs in os.walk(src_path):
                    for f in fs:
                        fp=os.path.join(rd,f)
                        try: mtimes[fp]=os.path.getmtime(fp)
                        except: pass
                try: mtimes[os.path.join(dir_path,'book.toml')]=os.path.getmtime(os.path.join(dir_path,'book.toml'))
                except: pass
                return mtimes
            last=get_mtimes()
            while True:
                time.sleep(1)
                cur=get_mtimes()
                changed=False
                if set(last.keys())!=set(cur.keys()): changed=True
                else:
                    for k,v in cur.items():
                        if last.get(k)!=v: changed=True; break
                if changed:
                    cfg=parse_book_toml(os.path.join(dir_path,'book.toml'))
                    cfg=env_override(cfg)
                    build_book(dir_path,cfg,dest_dir,open_browser=False)
                    last=cur
    except KeyboardInterrupt:
        pass
    except Exception as e:
        sys.stderr.write(f"Error: {e}\n"); sys.exit(1)

