def parse_book_toml(path):
    cfg={"book":{"title":None,"authors":[],"language":"en","src":"src","description":""},"build":{"build-dir":"book","create-missing":True,"extra-watch-dirs":[]},"output":{"html":{}}}
    if not os.path.exists(path):
