        if "book" in data:
            for k,v in data["book"].items():
                cfg["book"][k]=v
        if "build" in data:
            for k,v in data["build"].items():
                cfg["build"][k]=v
        if "output" in data and "html" in data["output"]:
            cfg["output"]["html"]=data["output"]["html"]
        return cfg
    except ImportError:
        pass
    current_section=None
    with open(path,'r',encoding='utf-8') as f:
        for line in f:
            l=line.strip()
            if not l or l.startswith('#'): continue
            if l.startswith('[') and l.endswith(']'):
                sec=l[1:-1]
                current_section=sec.split('.')[0] if '.' in sec else sec
                continue
            if '=' in l:
                k,v=l.split('=',1)
                k=k.strip(); v=v.strip()
                if v.startswith('"') and v.endswith('"'): v=v[1:-1]
                elif v.startswith("'") and v.endswith("'"): v=v[1:-1]
                elif v.lower()=='true': v=True
                elif v.lower()=='false': v=False
                if current_section=='book':
                    if k in ('title','src','language','description'): cfg['book'][k]=v
                elif current_section=='build':
                    if k=='build-dir': cfg['build']['build-dir']=v
                    elif k=='create-missing': cfg['build']['create-missing']=v if isinstance(v,bool) else (str(v).lower()=='true')
    return cfg

def env_override(cfg):
    for ek,val in os.environ.items():
        if not ek.startswith('MDBOOK_'): continue
        rest=ek[len('MDBOOK_'):]
        try:
            import json as js
            pv=js.loads(val)
        except:
            pv=val
        parts=rest.split('__')
        keys=[p.lower().replace('_','-') for p in parts]
        if len(keys)>=2:
            if keys[0]=='book' and len(keys)==2:
                cfg['book'][keys[1]]=pv
            elif keys[0]=='build' and len(keys)==2:
                cfg['build'][keys[1]]=pv
    return cfg

def get_src_dir(root,cfg):
    src=cfg['book'].get('src') or 'src'
    sp=src if os.path.isabs(src) else os.path.join(root,src)
    return src, sp

def get_dest_dir(root,cfg,cli_dest=None):
    if cli_dest:
        return cli_dest if os.path.isabs(cli_dest) else os.path.join(root,cli_dest)
    bd=cfg['build'].get('build-dir') or 'book'
    return bd if os.path.isabs(bd) else os.path.join(root,bd)

def parse_summary(summary_path):
    if not os.path.exists(summary_path): return None,None
    with open(summary_path,'r',encoding='utf-8') as f:
        lines=f.readlines()
    toc_tree=[]
    has_numbered=False
    parents=[(-1,toc_tree)]
    for raw in lines:
        line=raw.rstrip('\n')
        stripped=line.strip()
        if not stripped: continue
        if stripped.startswith('#'):
            m=re.match(r'^(#{1,})\s*(.*)$',stripped)
            if m:
                level=len(m.group(1)); title=m.group(2).strip()
                if level==1:
                    node={'type':'part','title':title}
                    toc_tree.append(node)
                    parents=[(-1,toc_tree)]
                    continue
                else:
                    continue
        if re.match(r'^\s*---+\s*$',line):
            node={'type':'separator'}
            parents[-1][1].append(node)
            continue
        m_list=re.match(r'^(\s*)([-*])\s+\[(.+?)\]\((.*?)\)\s*$',line)
        if m_list:
            indent=len(m_list.group(1).replace('\t','    '))
            title=m_list.group(3); path=m_list.group(4).strip()
            if path=="":
                node={'type':'draft','title':title,'path':None,'level':indent,'children':[]}
                while parents and parents[-1][0]>=indent: parents.pop()
                if not parents: parents=[(-1,toc_tree)]
                parents[-1][1].append(node)
                parents.append((indent,node['children']))
                has_numbered=True
                continue
            else:
                node={'type':'numbered','title':title,'path':path,'level':indent,'children':[]}
                while parents and parents[-1][0]>=indent: parents.pop()
                if not parents: parents=[(-1,toc_tree)]
                parents[-1][1].append(node)
                parents.append((indent,node['children']))
                has_numbered=True
                continue
        m_bracket=re.match(r'^\s*\[(.+?)\]\((.*?)\)\s*$',line)
        if m_bracket:
            title=m_bracket.group(1); path=m_bracket.group(2).strip()
            if path=="":
                node={'type':'draft','title':title,'path':None,'level':0,'children':[]}
            else:
                node={'type':'prefix' if not has_numbered else 'suffix','title':title,'path':path}
            toc_tree.append(node)
            parents=[(-1,toc_tree)]
            continue
    return toc_tree, has_numbered

def flatten_chapters(toc_tree):
    res=[]
    def walk(nodes):
        for n in nodes:
            if n['type'] in ('numbered','prefix','suffix'):
                res.append(n)
                if n.get('children'): walk(n['children'])
            elif n['type']=='draft':
                if n.get('children'): walk(n['children'])
    walk(toc_tree)
    return res

def assign_numbers(toc_tree):
    counters=[]
    def walk(nodes,depth=0):
        for node in nodes:
            if node['type'] in ('numbered','draft'):
                if len(counters)<=depth: counters.append(0)
                counters[depth]+=1
                del counters[depth+1:]
                num_str='.'.join(str(c) for c in counters)
                node['number']=num_str
                node['number_dot']=num_str+'.'
                if node.get('children'): walk(node['children'],depth+1)
            else:
                if node.get('children'): walk(node['children'],depth)
    walk(toc_tree)

