            if start is not None: s_idx=start-1
            if end is not None: e_idx=end
            s_idx=max(0,s_idx); e_idx=min(len(lines),e_idx)
            return ''.join(lines[s_idx:e_idx])
    def handle_rustdoc_include(target):
        fpath,extra=read_file(target)
        if fpath is None: return None
        with open(fpath,'r',encoding='utf-8',errors='ignore') as ff: lines=ff.readlines()
        if not extra or (len(extra)==1 and extra[0]==''): return ''.join(lines)
        if len(extra)==1 and not re.match(r'^\d*$',extra[0]):
            anchor=extra[0]
            start=None; end=None
            for i,l in enumerate(lines):
                if re.search(r'ANCHOR:\s*'+re.escape(anchor),l):
                    if start is None: start=i+1
            for i,l in enumerate(lines):
                if re.search(r'ANCHOR_END:\s*'+re.escape(anchor),l):
                    if start is not None and i>start: end=i; break
            if start is not None and end is not None:
                visible=set(range(start,end))
                filtered=set()
                for idx in visible:
                    if re.search(r'ANCHOR',lines[idx]): continue
                    filtered.add(idx)
                out=[]
                for idx,l in enumerate(lines):
                    if idx in filtered: out.append(l)
                    else:
                        out.append("#\n" if l.strip()=="" else "# "+l)
                return ''.join(out)
            else: return ""
        visible_start=None; visible_end=None
        if len(extra)==1:
            if re.match(r'^\d+$',extra[0]):
                ln=int(extra[0]); visible_start=ln-1; visible_end=ln
        elif len(extra)==2:
            a,b=extra[0],extra[1]
            if a=='' and b!='' and re.match(r'^\d+$',b): visible_start=0; visible_end=int(b)
            elif a!='' and b=='' and re.match(r'^\d+$',a): visible_start=int(a)-1; visible_end=len(lines)
            elif re.match(r'^\d+$',a) and re.match(r'^\d+$',b): visible_start=int(a)-1; visible_end=int(b)
        if visible_start is None: visible_start=0; visible_end=len(lines)
        out=[]
        for idx,l in enumerate(lines):
            if visible_start<=idx<visible_end: out.append(l)
            else: out.append("#\n" if l.strip()=="" else "# "+l)
        return ''.join(out)
    pattern=re.compile(r'\{\{#(include|playground|rustdoc_include)\s+([^}]+?)\}\}')
    def repl(m):
        typ=m.group(1); target=m.group(2).strip()
        if typ=='playground':
            parts=target.split(); file_part=parts[0]
            fpath,extra=read_file(file_part)
            if fpath is None:
                sys.stderr.write(f'2026-09-08 17:49:19 [ERROR] (mdbook_driver::builtin_preprocessors::links): Error updating "{{{{#{typ} {target}}}}}", Could not read file for link {{{{#{typ} {target}}}}} ({os.path.join(curr_dir,file_part)})\n')
                sys.stderr.write(f'2026-09-08 17:49:19 [WARN] (mdbook_driver::builtin_preprocessors::links): Caused By: No such file or directory (os error 2)\n')
                return m.group(0)
            with open(fpath,'r',encoding='utf-8',errors='ignore') as ff: content=ff.read()
            attrs=""
            if len(parts)>1: attrs=","+",".join(parts[1:])
            return f"\n```rust{attrs}\n{content}\n```\n"
        elif typ=='include':
            fpath,extra=read_file(target)
            if fpath is None:
                sys.stderr.write(f'2026-09-08 17:49:19 [ERROR] (mdbook_driver::builtin_preprocessors::links): Error updating "{{{{#include {target}}}}}", Could not read file for link {{{{#include {target}}}}} ({os.path.join(curr_dir,target.split(":")[0])})\n')
                sys.stderr.write(f'2026-09-08 17:49:19 [WARN] (mdbook_driver::builtin_preprocessors::links): Caused By: No such file or directory (os error 2)\n')
                return m.group(0)
            content=extract_content(fpath,extra)
            if content is None:
                sys.stderr.write(f'2026-09-08 17:49:19 [ERROR] (mdbook_driver::builtin_preprocessors::links): Error updating "{{{{#include {target}}}}}", Could not read file for link {{{{#include {target}}}}} ({fpath})\n')
                sys.stderr.write(f'2026-09-08 17:49:19 [WARN] (mdbook_driver::builtin_preprocessors::links): Caused By: No such file or directory (os error 2)\n')
                return m.group(0)
            return content
        elif typ=='rustdoc_include':
            content=handle_rustdoc_include(target)
            if content is None:
                sys.stderr.write(f'2026-09-08 17:49:19 [ERROR] (mdbook_driver::builtin_preprocessors::links): Error updating "{{{{#rustdoc_include {target}}}}}", Could not read file for link {{{{#rustdoc_include {target}}}}} ({os.path.join(curr_dir,target.split(":")[0])})\n')
                sys.stderr.write(f'2026-09-08 17:49:19 [WARN] (mdbook_driver::builtin_preprocessors::links): Caused By: No such file or directory (os error 2)\n')
                return m.group(0)
            return content
        return m.group(0)
    new_text=md_text
    for _ in range(10):
        rep=pattern.sub(repl,new_text)
        if rep==new_text: break
        new_text=rep
    return new_text

def extract_title_from_md(md_text):
    m=re.search(r'\{\{#title\s+([^}]+)\}\}',md_text)
    if m: return m.group(1).strip()
    for line in md_text.splitlines():
        hm=re.match(r'^#\s+(.*)',line)
        if hm: return hm.group(1).strip()
    return None

def load_static_assets():
    possible=[os.path.join(os.path.dirname(__file__),'static'),'/tmp/bundled_static','static','./static','/workspace/static']
    assets={}
    for p in possible:
        if os.path.isdir(p):
            for root,dirs,files in os.walk(p):
                for f in files:
                    full=os.path.join(root,f)
                    rel=os.path.relpath(full,p)
                    try:
                        with open(full,'rb') as fh: data=fh.read()
                        assets[rel]=data
                    except: pass
            if assets: return assets
    return {}

def copy_static_assets(dest_dir,theme_dir=None):
    os.makedirs(dest_dir,exist_ok=True)
    default_assets=load_static_assets()
    for rel,data in default_assets.items():
        if rel=='index.hbs' or rel.endswith('.hbs'): continue
        dest_path=os.path.join(dest_dir,rel)
        os.makedirs(os.path.dirname(dest_path),exist_ok=True)
        with open(dest_path,'wb') as out: out.write(data)
    if theme_dir and os.path.isdir(theme_dir):
        for root,dirs,files in os.walk(theme_dir):
            for f in files:
                full=os.path.join(root,f)
                rel=os.path.relpath(full,theme_dir)
                dest_path=os.path.join(dest_dir,rel)
                os.makedirs(os.path.dirname(dest_path),exist_ok=True)
                shutil.copy2(full,dest_path)
    with open(os.path.join(dest_dir,'.nojekyll'),'w',encoding='utf-8') as out:
        out.write("This file makes sure that Github Pages doesn't process mdBook's output.\n")

def convert_path_to_html(path):
    if not path: return ""
    p=path
    while p.startswith('./'): p=p[2:]
    if p.lower().endswith('.md'): p=p[:-3]+'.html'
    dirname=os.path.dirname(p); basename=os.path.basename(p)
    if basename.lower()=='readme.html':
        p=os.path.join(dirname,'index.html') if dirname else 'index.html'
    p=p.replace('\\','/')
    return p

def generate_toc_html(toc_tree,path_to_root=""):
    def render_nodes(nodes):
        parts=[]
        for node in nodes:
            t=node['type']
            if t=='part':
                parts.append(f'<li class="part-title">{html.escape(node["title"])}</li>')
            elif t=='separator':
                parts.append(f'<li class="spacer"></li>')
            elif t=='prefix':
                hp=convert_path_to_html(node['path'])
                parts.append(f'<li class="chapter-item expanded affix "><a href="{html.escape(hp)}" target="_parent">{html.escape(node["title"])}</a></li>')
            elif t=='suffix':
                hp=convert_path_to_html(node['path'])
                parts.append(f'<li class="chapter-item expanded affix "><a href="{html.escape(hp)}" target="_parent">{html.escape(node["title"])}</a></li>')
            elif t=='numbered':
                hp=convert_path_to_html(node['path'])
                number=node.get('number_dot') or ""
                num_html=f'<strong aria-hidden="true">{html.escape(number)}</strong> ' if number else ""
                if node.get('children'):
                    child_html=render_nodes(node['children'])
                    parts.append(f'<li class="chapter-item expanded "><a href="{html.escape(hp)}" target="_parent">{num_html}{html.escape(node["title"])}</a></li><li><ol class="section">{child_html}</ol></li>')
                else:
                    parts.append(f'<li class="chapter-item expanded "><a href="{html.escape(hp)}" target="_parent">{num_html}{html.escape(node["title"])}</a></li>')
            elif t=='draft':
                number=node.get('number_dot') or ""
                num_html=f'<strong aria-hidden="true">{html.escape(number)}</strong> ' if number else ""
                parts.append(f'<li class="chapter-item expanded "><div>{num_html}{html.escape(node["title"])}</div></li>')
        return ''.join(parts)
    inner=render_nodes(toc_tree)
    full=f'''<!DOCTYPE HTML>
<html lang="en" class="light" dir="ltr">
    <head>
        <!-- sidebar iframe generated using mdBook

        This is a frame, and not included directly in the page, to control the total size of the
        book. The TOC contains an entry for each page, so if each page includes a copy of the TOC,
        the total size of the page becomes O(n**2).

        The frame is only used as a fallback when JS is turned off. When it's on, the sidebar is
        instead added to the main page by `toc.js` instead. The JavaScript mode is better
        because, when running in a `file:///` URL, the iframed page would not be Same-Origin as
        the rest of the page, so the sidebar and the main page theme would fall out of sync.
        -->
        <meta charset="UTF-8">
        <meta name="robots" content="noindex">
        <!-- Custom HTML head -->
        <meta name="viewport" content="width=device-width, initial-scale=1">
        <meta name="theme-color" content="#ffffff">
        <link rel="stylesheet" href="{path_to_root}css/variables.css">
        <link rel="stylesheet" href="{path_to_root}css/general.css">
        <link rel="stylesheet" href="{path_to_root}css/chrome.css">
        <link rel="stylesheet" href="{path_to_root}css/print.css" media="print">
        <!-- Fonts -->
        <link rel="stylesheet" href="{path_to_root}FontAwesome/css/font-awesome.css">
        <link rel="stylesheet" href="{path_to_root}fonts/fonts.css">
        <!-- Custom theme stylesheets -->
    </head>
    <body class="sidebar-iframe-inner">
        <ol class="chapter">{inner}</ol>
    </body>
</html>
'''
    return full, f'<ol class="chapter">{inner}</ol>'

def generate_toc_js(toc_inner_ol):
    js_inner=toc_inner_ol.replace(' target="_parent"','')
    js_escaped=js_inner.replace('\\','\\\\').replace("'","\\'")
    return f'''// Populate the sidebar
//
// This is a script, and not included directly in the page, to control the total size of the book.
// The TOC contains an entry for each page, so if each page includes a copy of the TOC,
// the total size of the page becomes O(n**2).
class MDBookSidebarScrollbox extends HTMLElement {{
    constructor() {{ super(); }}
    connectedCallback() {{
        this.innerHTML = '{js_escaped}';
        let current_page = document.location.href.toString().split("#")[0].split("?")[0];
        if (current_page.endsWith("/")) {{ current_page += "index.html"; }}
        var links = Array.prototype.slice.call(this.querySelectorAll("a"));
        var l = links.length;
        for (var i = 0; i < l; ++i) {{
            var link = links[i];
            var href = link.getAttribute("href");
            if (href && !href.startsWith("#") && !/^(?:[a-z+]+:)?\\/\\//.test(href)) {{ link.href = path_to_root + href; }}
            if (link.href === current_page || (i === 0 && path_to_root === "" && current_page.endsWith("/index.html"))) {{
                link.classList.add("active");
                var parent = link.parentElement;
                if (parent && parent.classList.contains("chapter-item")) {{ parent.classList.add("expanded"); }}
                while (parent) {{
                    if (parent.tagName === "LI" && parent.previousElementSibling) {{
                        if (parent.previousElementSibling.classList.contains("chapter-item")) {{ parent.previousElementSibling.classList.add("expanded"); }}
                    }}
                    parent = parent.parentElement;
                }}
            }}
        }}
        this.addEventListener('click', function(e) {{
            if (e.target.tagName === 'A') {{ sessionStorage.setItem('sidebar-scroll', this.scrollTop); }}
        }}, {{ passive: true }});
        var sidebarScrollTop = sessionStorage.getItem('sidebar-scroll');
        sessionStorage.removeItem('sidebar-scroll');
        if (sidebarScrollTop) {{ this.scrollTop = sidebarScrollTop; }} else {{
            var activeSection = document.querySelector('#sidebar .active');
            if (activeSection) {{ activeSection.scrollIntoView({{ block: 'center' }}); }}
        }}
        var sidebarAnchorToggles = document.querySelectorAll('#sidebar a.toggle');
        function toggleSection(ev) {{ ev.currentTarget.parentElement.classList.toggle('expanded'); }}
        Array.from(sidebarAnchorToggles).forEach(function (el) {{ el.addEventListener('click', toggleSection); }});
    }}
}}
window.customElements.define("mdbook-sidebar-scrollbox", MDBookSidebarScrollbox);
'''

def md_to_html(md_text,src_dir,file_path):
    md_text=preprocess_includes(md_text,src_dir,file_path)
    lines=md_text.splitlines()
    html_output=[]
    in_fence=False; fence_lines=[]; fence_info=""; para_lines=[]
    def flush_para():
        nonlocal para_lines, html_output
        if not para_lines: return
        text=' '.join(para_lines).strip()
        para_lines=[]
        if not text: return
        esc=html.escape(text)
        esc=re.sub(r'!\[(.*?)\]\((.*?)\)', lambda m: f'<img src="{html.escape(m.group(2))}" alt="{html.escape(m.group(1))}" />', esc)
        def link_repl(m):
            txt=m.group(1); url=m.group(2)
            if '://' not in url and not url.startswith('#'):
                url=re.sub(r'\.md(#|$)', r'.html\1', url)
                if re.search(r'readme\.html$',url,re.IGNORECASE):
                    url=re.sub(r'[^/]*readme\.html$','index.html',url,flags=re.IGNORECASE)
                if url.startswith('./'): url=url[2:]
            return f'<a href="{html.escape(url)}">{txt}</a>'
        esc=re.sub(r'\[(.*?)\]\((.*?)\)', link_repl, esc)
        esc=re.sub(r'\*\*(.+?)\*\*', r'<strong>\1</strong>', esc)
        esc=re.sub(r'\*(.+?)\*', r'<em>\1</em>', esc)
        esc=re.sub(r'`([^`]+?)`', r'<code>\1</code>', esc)
        html_output.append(f'<p>{esc}</p>')
    for raw_line in lines+[""]:
        line=raw_line.rstrip('\n')
        if line.strip().startswith('```'):
            if in_fence:
                code_content='\n'.join(fence_lines)
                code_esc=html.escape(code_content)
                lang=fence_info.strip(); lang_class=""
                if lang:
                    m=re.split(r'[, \t]',lang)
                    if m:
                        first=m[0]
                        if first: lang_class=f' class="language-{html.escape(first)}"'
                if fence_info.strip().startswith('rust'):
                    html_output.append(f'<pre><pre class="playground"><code{lang_class}>{code_esc}</code></pre></pre>')
                else:
                    html_output.append(f'<pre><code{lang_class}>{code_esc}</code></pre>')
                in_fence=False; fence_lines=[]; fence_info=""
                continue
            else:
                flush_para()
                in_fence=True; fence_info=line.strip()[3:]; fence_lines=[]
                continue
        if in_fence:
            fence_lines.append(line); continue
        if line.strip()=="":
            flush_para(); continue
        m=re.match(r'^(#{1,6})\s+(.*)$',line)
        if m:
            flush_para()
            level=len(m.group(1)); text=m.group(2).strip()
            text=re.sub(r'\s+#+\s*$','',text)
            slug=text.lower(); slug=re.sub(r'[^a-z0-9]+','-',slug); slug=slug.strip('-')
            if not slug: slug="section"
            esc_text=html.escape(text)
            esc_text=re.sub(r'\*\*(.+?)\*\*', r'<strong>\1</strong>', esc_text)
            esc_text=re.sub(r'\*(.+?)\*', r'<em>\1</em>', esc_text)
            esc_text=re.sub(r'`([^`]+?)`', r'<code>\1</code>', esc_text)
            html_output.append(f'<h{level} id="{slug}"><a class="header" href="#{slug}">{esc_text}</a></h{level}>')
            continue
        m_ul=re.match(r'^\s*[-*]\s+(.*)$',line)
        m_ol=re.match(r'^\s*\d+\.\s+(.*)$',line)
        if m_ul or m_ol:
            flush_para()
            content=(m_ul.group(1) if m_ul else m_ol.group(1))
            esc_content=html.escape(content)
            def _link2(mm):
                u=mm.group(2)
                u=re.sub(r"\.md(#|$)", r".html\1", u)
                return f'<a href="{html.escape(u)}">{mm.group(1)}</a>'
            esc_content=re.sub(r'\[(.*?)\]\((.*?)\)', _link2, esc_content)
            esc_content=re.sub(r'\*\*(.+?)\*\*', r'<strong>\1</strong>', esc_content)
            esc_content=re.sub(r'\*(.+?)\*', r'<em>\1</em>', esc_content)
            esc_content=re.sub(r'`([^`]+?)`', r'<code>\1</code>', esc_content)
            if m_ul: html_output.append(f'<ul>\n<li>{esc_content}</li>\n</ul>')
            else: html_output.append(f'<ol>\n<li>{esc_content}</li>\n</ol>')
            continue
        para_lines.append(line.strip())
    flush_para()
    return '\n'.join(html_output)

