    theme_dir=os.path.join(root,'theme')
    if not os.path.isdir(theme_dir): theme_dir=None
    copy_static_assets(dest_dir,theme_dir)
    chapter_htmls=[]
    nav_list=[]
    for node in flat:
        hp=convert_path_to_html(node['path'])
        nav_list.append({'title':node['title'],'html_path':hp,'node':node})
    for idx,nav in enumerate(nav_list):
        node=nav['node']; html_path=nav['html_path']
        md_rel=node['path'].lstrip('./')
        while md_rel.startswith('./'): md_rel=md_rel[2:]
        md_full=os.path.join(src_path,md_rel)
        if not os.path.exists(md_full): continue
        with open(md_full,'r',encoding='utf-8') as f: md_content=f.read()
        title=extract_title_from_md(md_content) or node['title']
        content_html=md_to_html(md_content,src_path,md_full)
        dir_part=os.path.dirname(html_path)
        if dir_part:
            depth=len(dir_part.split('/'))
            path_to_root='../'*depth
        else:
            path_to_root=""
        prev_info=nav_list[idx-1] if idx>0 else None
        next_info=nav_list[idx+1] if idx < len(nav_list)-1 else None
        chapter_htmls.append({'title':title,'content_html':content_html,'book_title':get_book_title(cfg),'language':get_language(cfg),'description':get_description(cfg),'path_to_root':path_to_root,'prev':prev_info,'next':next_info,'html_path':html_path,'md_path':md_full,'node':node})
    toc_html_full,toc_inner=generate_toc_html(toc_tree,path_to_root="")
    toc_js=generate_toc_js(toc_inner)
    for ch in chapter_htmls:
        page_html=generate_html_page(ch['title'],ch['content_html'],ch['book_title'],ch['language'],ch['description'],ch['path_to_root'],ch['prev'],ch['next'],toc_html_full,toc_inner)
        dest_file=os.path.join(dest_dir,ch['html_path'])
        os.makedirs(os.path.dirname(dest_file),exist_ok=True)
        with open(dest_file,'w',encoding='utf-8') as out: out.write(page_html)
    index_path=os.path.join(dest_dir,'index.html')
    if not os.path.exists(index_path) and chapter_htmls:
        first=chapter_htmls[0]
        first_file=os.path.join(dest_dir,first['html_path'])
        if os.path.exists(first_file):
            shutil.copy2(first_file,index_path)
    with open(os.path.join(dest_dir,'404.html'),'w',encoding='utf-8') as out:
        out.write(generate_404_page(get_book_title(cfg),get_language(cfg),get_description(cfg)))
    with open(os.path.join(dest_dir,'toc.html'),'w',encoding='utf-8') as out:
        out.write(toc_html_full)
    with open(os.path.join(dest_dir,'toc.js'),'w',encoding='utf-8') as out:
        out.write(toc_js)
    print_main=""
    for ch in chapter_htmls:
        print_main+=f'<div style="break-before: page; page-break-before: always;"></div>{ch["content_html"]}\n'
    print_html_content=f'''<!DOCTYPE HTML>
<html lang="{html.escape(get_language(cfg))}" class="light sidebar-visible" dir="ltr">
    <head>
        <!-- Book generated using mdBook -->
        <meta charset="UTF-8">
