    <div id="body-container">
        <div id="content" class="content">
            <main>
                {print_main}
            </main>
        </div>
    </div>
    <script src="clipboard.min.js"></script>
    <script src="highlight.js"></script>
    <script src="book.js"></script>
    </body>
</html>
'''
    with open(os.path.join(dest_dir,'print.html'),'w',encoding='utf-8') as out:
        out.write(print_html_content)
    doc_urls=[]; docs={}; doc_info={}; doc_id=0
    for ch in chapter_htmls:
        with open(ch['md_path'],'r',encoding='utf-8') as ff: md_text=ff.read()
        preprocessed=preprocess_includes(md_text,src_path,ch['md_path'])
        header_counts={}
        def slugify(text):
            s=text.lower(); s=re.sub(r'[^a-z0-9]+','-',s); s=s.strip('-')
            if not s: s="section"
            cnt=header_counts.get(s,0); header_counts[s]=cnt+1
            return f"{s}-{cnt}" if cnt>0 else s
        temp_sections=[]
        cur_title=None; cur_id=None; cur_body=[]
        for line in preprocessed.splitlines():
            hm=re.match(r'^(#{1,3})\s+(.*)$',line.strip())
            if hm:
                if cur_title is not None:
                    temp_sections.append((cur_title,cur_id,'\n'.join(cur_body)))
                cur_title=hm.group(2).strip(); cur_id=slugify(cur_title); cur_body=[]
            else:
                cur_body.append(line)
        if cur_title is not None:
            temp_sections.append((cur_title,cur_id,'\n'.join(cur_body)))
        else:
            temp_sections.append((ch['title'],'content','\n'.join(cur_body)))
        for sec_title,sec_id,sec_body in temp_sections:
            url=f"{ch['html_path']}#{sec_id}"
            doc_urls.append(url)
            plain=sec_body
            plain=re.sub(r'```.*?```','',plain,flags=re.S)
            plain=re.sub(r'`[^`]*`','',plain)
            plain=re.sub(r'\[([^\]]+)\]\([^\)]+\)',r'\1',plain)
            plain=re.sub(r'!\[[^\]]*\]\([^\)]+\)','',plain)
            plain=re.sub(r'\*\*([^\*]+)\*\*',r'\1',plain)
            plain=re.sub(r'\*([^\*]+)\*',r'\1',plain)
            plain=re.sub(r'#+\s*','',plain)
            plain=re.sub(r'[-*]\s+','',plain)
            plain=re.sub(r'\s+',' ',plain).strip()
            doc_key=str(doc_id)
            breadcrumbs=f"{ch['title']} » {sec_title}" if sec_title!=ch['title'] else sec_title
            docs[doc_key]={"body":plain,"breadcrumbs":breadcrumbs,"id":doc_key,"title":sec_title}
            doc_info[doc_key]={"body":len(plain.split()),"breadcrumbs":len(breadcrumbs.split()),"title":len(sec_title.split())}
            doc_id+=1
    document_store={"docInfo":doc_info,"docs":docs,"length":len(docs),"save":True}
    index={"doc_urls":doc_urls,"index":{"documentStore":document_store,"fields":["title","body","breadcrumbs"],"index":{"body":{"root":{}},"breadcrumbs":{"root":{}},"title":{"root":{}}},"lang":"English","pipeline":["trimmer","stopWordFilter","stemmer"],"ref":"id","version":"0.9.5"},"results_options":{"limit_results":30,"teaser_word_count":30},"search_options":{"bool":"OR","expand":True,"fields":{"body":{"boost":1},"breadcrumbs":{"boost":1},"title":{"boost":2}}}}
    json_str=json.dumps(index,ensure_ascii=False)
    json_escaped=json_str.replace('\\','\\\\').replace("'","\\'").replace('</','<\\/') 
    with open(os.path.join(dest_dir,'searchindex.js'),'w',encoding='utf-8') as out:
        out.write(f"window.search = Object.assign(window.search, JSON.parse('{json_escaped}'));")
    for root_dir,dirs,files in os.walk(src_path):
