                os.makedirs(os.path.dirname(dest),exist_ok=True)
                with open(dest,'wb') as out: out.write(data)
    title=args.title; ignore=args.ignore
    if not args.force:
        if ignore is None:
            sys.stdout.write("\nDo you want a .gitignore to be created? (y/n)\n")
            sys.stdout.flush()
            ans=sys.stdin.readline().strip()
            ignore='git' if ans.lower()=='y' else 'none'
        if title is None:
