def cmd_clean(args):
    dir_path=os.path.abspath(args.dir or '.')
    cfg=parse_book_toml(os.path.join(dir_path,'book.toml'))
    cfg=env_override(cfg)
    dest_dir=get_dest_dir(dir_path,cfg,args.dest_dir)
    src_name,src_path=get_src_dir(dir_path,cfg)
    if not os.path.exists(os.path.join(src_path,'SUMMARY.md')):
        error_exit(f"Couldn't open SUMMARY.md in \"{src_path}\" directory","No such file or directory (os error 2)")
    total_files=0; total_size=0
    if os.path.exists(dest_dir):
        for root,dirs,files in os.walk(dest_dir):
            for f in files:
                fp=os.path.join(root,f)
                try: total_files+=1; total_size+=os.path.getsize(fp)
                except: pass
        shutil.rmtree(dest_dir)
    if total_files==0:
        sys.stdout.write("Removed 0 files\n")
    else:
        if total_size<1024: size_str=f"{total_size}B"
        elif total_size<1024*1024: size_str=f"{total_size/1024:.2f}KiB"
        elif total_size<1024*1024*1024: size_str=f"{total_size/(1024*1024):.2f}MiB"
        else: size_str=f"{total_size/(1024*1024*1024):.2f}GiB"
        sys.stdout.write(f"Removed {total_files} files, {size_str} total\n")

