def main():
    raw = sys.argv[1:]
    # version handling top level
    if raw and raw[0] in ('-V','--version'):
        sys.stdout.write(f"mdbook {VERSION}\n")
        sys.exit(0)
    if len(raw)>=1 and raw[0] in ('help','--help','-h'):
        if len(raw)>=2 and raw[1] in ('init','build','clean','test','completions','watch','serve'):
            print_help(raw[1])
            sys.exit(0)
        else:
            print_help('main')
            sys.exit(0)
    # check subcommand version in any position
    if raw:
        for i,arg in enumerate(raw):
            if arg in ('init','build','test','clean','completions','watch','serve'):
                rest=raw[i+1:]
                if '-V' in rest or '--version' in rest:
                    sys.stdout.write(f"mdbook-{arg} {VERSION}\n")
                    sys.exit(0)
                if '-h' in rest or '--help' in rest:
                    print_help(arg)
                    sys.exit(0)
