    # if no command, show main help
    if not raw:
        print_help('main')
        sys.exit(0)

    # Manual argument parsing (since we need exact help on error, we will use simple parsing and let argparse handle errors? But we want error messages same as clap)
    # For error handling, we will attempt to mimic clap errors: "error: unexpected argument '--invalid' found" etc
    # We'll implement minimal parsing for each subcommand

    cmd = raw[0]
    if cmd not in ('init','build','test','clean','completions','watch','serve','help'):
        sys.stderr.write(f"error: unrecognized subcommand '{cmd}'\n\n")
        sys.stderr.write(f"For more information, try '--help'.\n")
        sys.exit(2)

    if cmd=='help':
        if len(raw)>=2 and raw[1] in ('init','build','clean','test','completions','watch','serve'):
            print_help(raw[1])
