            print_help('main')
        sys.exit(0)

    # Parse common: we need to extract --help, --version already handled
    # We'll create a simple parser that returns args object

    class Args: pass

    # Helper to parse options
    def parse_common(args_list):
        # returns (dir, dest_dir, open_flag, watcher, hostname, port, title, theme, force, ignore, shell, chapter, library_path)
        # We'll use dict
        result = {'dir': None, 'dest_dir': None, 'open': False, 'watcher': 'poll', 'hostname': 'localhost', 'port': '3000', 'title': None, 'theme': False, 'force': False, 'ignore': None, 'shell': None, 'chapter': None, 'library_path': None}
        i=0
        while i < len(args_list):
            a=args_list[i]
            if a in ('-h','--help'):
                # help already handled, but if we get here, print help for current cmd
                # Determine current cmd from outer scope
                print_help(cmd)
                sys.exit(0)
            elif a in ('-V','--version'):
                sys.stdout.write(f"mdbook-{cmd} {VERSION}\n")
                sys.exit(0)
            elif a=='--theme':
                result['theme']=True
            elif a=='--force':
                result['force']=True
            elif a=='--title':
                if i+1>=len(args_list):
                    sys.stderr.write(f"error: a value is required for '--title <title>' but none was supplied\n\nFor more information, try '--help'.\n")
                    sys.exit(2)
                result['title']=args_list[i+1]
