                sys.exit(0)
            if a.startswith('-'):
                sys.stderr.write(f"error: unexpected argument '{a}' found\n\nUsage: {os.path.basename(sys.argv[0])} completions <SHELL>\n\nFor more information, try '--help'.\n")
                sys.exit(2)
            else:
                if shell is None:
                    shell=a
                else:
                    sys.stderr.write(f"error: unexpected argument '{a}' found\n\nUsage: {os.path.basename(sys.argv[0])} completions <SHELL>\n\nFor more information, try '--help'.\n")
                    sys.exit(2)
            i+=1
        if shell not in ('bash','elvish','fish','powershell','zsh'):
            sys.stderr.write(f"error: invalid value '{shell}' for '<SHELL>'\n  [possible values: bash, elvish, fish, powershell, zsh]\n\nFor more information, try '--help'.\n")
            sys.exit(2)
        aobj=Args()
        aobj.shell=shell
        cmd_completions(aobj)

if __name__=='__main__':
    main()
